package com.likerts.sdk
import kotlinx.coroutines.test.runTest
import org.junit.Assert.*
import org.junit.Test
class OfflineQueueTest{class Adapter:OfflineSecureAdapter{override val protectionProfile="android_keystore_aes_gcm";var records=listOf<ByteArray>();override suspend fun load()=records.map{it.copyOf()};override suspend fun replace(records:List<ByteArray>){this.records=records.map{it.copyOf()}};override suspend fun seal(clear:ByteArray)=byteArrayOf(42)+clear.map{(it.toInt() xor 91).toByte()}+byteArrayOf(24);override suspend fun open(sealed:ByteArray):ByteArray{require(sealed.first()==42.toByte()&&sealed.last()==24.toByte());return sealed.sliceArray(1 until sealed.lastIndex).map{(it.toInt() xor 91).toByte()}.toByteArray()}}
@Test fun encryptedOldestFirstRetryTerminalAndQuarantine()=runTest{assertThrows(IllegalArgumentException::class.java){OfflineQueue(object:OfflineSecureAdapter by Adapter(){override val protectionProfile="plaintext"})};val adapter=Adapter();val seen=mutableListOf<String>();val queue=OfflineQueue(adapter);queue.enqueue("a","{\"secret\":\"answer\"}".encodeToByteArray(),"one");queue.enqueue("b","{}".encodeToByteArray(),"two");queue.enqueue("c","{}".encodeToByteArray(),"three");assertFalse(adapter.records.first().decodeToString().contains("answer"));val report=queue.flush(credential={"token"},send={collectionId,_,payload->seen+=payload.decodeToString();when(seen.size){1->OfflineAttempt(429,retryAfterSeconds=60);2->OfflineAttempt(403);else->OfflineAttempt(200,responseId="r",receiptCollectionId=collectionId,accepted=true)}});assertEquals(3,report.attempted);assertEquals(1,report.accepted);assertEquals(1,report.status.pending);assertEquals(1,report.status.blockedByReason[OfflineReason.revoked]);adapter.records[0][3]=(adapter.records[0][3].toInt() xor 1).toByte();assertEquals(1,queue.snapshot().quarantined);assertEquals(1,queue.purgeQuarantined());assertEquals(0,queue.snapshot().quarantined)}}
